/**
 * Demo product fixture for `npm run dev` (no WP backend).
 *
 * Source: demo-store/docs/sample-products.json — generated by
 * scripts/fetch-product-imagery.mjs. Re-run that script to refresh.
 *
 * The transform below shapes each fixture entry into the WooCommerce Store
 * API response shape, so the same components work against demo data and
 * a live store with no branching.
 */

import fixture from '../../../../docs/sample-products.json';

const isWp = typeof window !== 'undefined' && Boolean(window.wpData);

/**
 * Resolve image URLs based on runtime context:
 *   - WP (built bundle served via WordPress theme): /wp-content/themes/.../public/products/<slug>.jpg
 *     The fixture stores the WP-style absolute path; pass through.
 *   - Vite dev / vite preview (no WP): public/ is served at site root, so
 *     strip the WP prefix.
 */
function resolveImage(wpPath) {
  if (!wpPath) return '';
  if (isWp) return wpPath;
  return wpPath.replace(/^.*\/public\//, '/');
}

function toMinorUnits(price) {
  return String(Math.round(price * 100));
}

function toStoreApiProduct(p) {
  const image = resolveImage(p.image);
  return {
    id: p.id,
    slug: p.slug,
    name: p.name,
    sku: p.sku,
    short_description: `<p>${p.short_description}</p>`,
    description: `<p>${p.description}</p>`,
    permalink: `/product/${p.slug}`,
    images: image ? [{ src: image, alt: p.name }] : [],
    prices: {
      price: toMinorUnits(p.price),
      regular_price: toMinorUnits(p.price),
      sale_price: toMinorUnits(p.price),
      currency_code: 'INR',
      currency_minor_unit: 2,
      currency_symbol: '₹',
    },
    categories: [],
    is_in_stock: true,
  };
}

export const demoProducts = fixture.products.map(toStoreApiProduct);

export function getDemoProductBySlug(slug) {
  return demoProducts.find((p) => p.slug === slug) || null;
}

export function emptyDemoCart() {
  return {
    items: [],
    items_count: 0,
    totals: {
      total_items: '0',
      total_price: '0',
      total_shipping: '0',
      total_tax: '0',
      currency_code: 'INR',
      currency_minor_unit: 2,
      currency_symbol: '₹',
    },
  };
}

/**
 * Tiny in-memory cart for demo mode. Mutations are not persisted across
 * page reloads — by design, since this branch only runs without a backend.
 */
let demoCart = emptyDemoCart();

function recompute() {
  let totalItemsMinor = 0;
  let count = 0;
  for (const item of demoCart.items) {
    const lineMinor = Number(item.prices.price) * item.quantity;
    item.totals = {
      line_subtotal: String(lineMinor),
      line_total: String(lineMinor),
      currency_code: 'INR',
      currency_minor_unit: 2,
      currency_symbol: '₹',
    };
    totalItemsMinor += lineMinor;
    count += item.quantity;
  }
  demoCart.items_count = count;
  demoCart.totals.total_items = String(totalItemsMinor);
  demoCart.totals.total_price = String(totalItemsMinor);
}

export function getDemoCart() {
  return structuredClone(demoCart);
}

export function addDemoItem({ id, quantity = 1 }) {
  const product = demoProducts.find((p) => p.id === id);
  if (!product) throw new Error(`Demo product ${id} not found`);

  const existing = demoCart.items.find((i) => i.id === id);
  if (existing) {
    existing.quantity += quantity;
  } else {
    demoCart.items.push({
      key: `demo-${id}`,
      id,
      quantity,
      name: product.name,
      images: product.images,
      prices: product.prices,
      totals: { line_subtotal: '0', line_total: '0' },
    });
  }
  recompute();
  return getDemoCart();
}

export function updateDemoItem({ key, quantity }) {
  const item = demoCart.items.find((i) => i.key === key);
  if (item) {
    if (quantity <= 0) {
      demoCart.items = demoCart.items.filter((i) => i.key !== key);
    } else {
      item.quantity = quantity;
    }
  }
  recompute();
  return getDemoCart();
}

export function removeDemoItem({ key }) {
  demoCart.items = demoCart.items.filter((i) => i.key !== key);
  recompute();
  return getDemoCart();
}

export function clearDemoCart() {
  demoCart = emptyDemoCart();
  return getDemoCart();
}
